import {petPortrait} from './pet-portraits.mjs?v=0.6';
import {PETS,GRADES,amount,canMaterials} from './economy.mjs?v=0.6';
import {petSlotCount,SLOT_LEVELS,deployedPets,gatherBoost,gatherSeconds} from './pet-data.mjs?v=0.6';
import {regionUnlocked} from './regions.mjs?v=0.6';
import {PET_EFFECTS} from './companions.mjs?v=0.6';
let selected=null,catalog='fox',filter='all',fuse=[];
export function renderPetDeck(which,c){if(which!=='pets')return false;const {game,openModal,showPanel,save,hud}=c,s=game.s,$=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];fuse=fuse.filter(id=>s.petRoster.some(p=>p.id===id));const it=s.petRoster.find(p=>p.id===selected),key=it?.species||catalog,p=PETS[key],slots=petSlotCount(s),refresh=()=>{hud();save();showPanel('pets');};
 const statsText=Object.entries(p.bonus).map(([k,n])=>`${{hp:'HP',mp:'MP',atk:'Công',def:'Thủ'}[k]} +${Math.round(n*(it?.rank||1)*(1+(it?.treasure||0)*.1))}`).join(' · '),speed=Object.entries(p.gather||{}).map(([k,n])=>`${{ore:'Đào khoáng',herb:'Hái thuốc',energy:'Hấp thu'}[k]} +${(n*(1+((it?.rank||1)-1)*.1+(it?.treasure||0)*.1)).toFixed(1)}%`).join(' · ');
 const roster=s.petRoster.filter(x=>filter==='all'||PETS[x.species].grade===Number(filter));
 openModal(`<span class="eyebrow">LONG MẠCH · LINH THÚ</span><h2>Đội hình pet · ${s.petDeck.length}/${slots} ô mở</h2><div class="panel-tabs"><button data-nav="loadout">Nhân vật</button><button data-nav="mounts">Thú cưỡi</button><button data-nav="skills">Kỹ năng</button><button data-nav="materials">Nguyên liệu</button></div><div class="pet-deck">${SLOT_LEVELS.map((lv,i)=>{const a=s.petRoster.find(x=>x.id===s.petDeck[i]);return `<button data-deck="${a?.id||''}" ${!a?'disabled':''} class="${a?'rarity-'+PETS[a.species].grade:''}"><b>Ô ${i+1}</b>${a?petPortrait(a.species):'<span>'+(i<slots?'+':'🔒')+'</span>'}<small>${a?PETS[a.species].name:i<slots?'Trống':'Cấp '+lv+' hoặc cốt truyện'}</small></button>`;}).join('')}</div><p>Mở ô lần lượt theo cấp 1/3/5/8/12/16/22/28/36/45 hoặc nhiệm vụ Vân Sơn 0/2/4/6/8/12 rồi hoàn thành Trúc Hải/Băng Hồ/Hỏa Sơn/Thiên Cung. Mỗi loài chỉ đeo một cá thể.</p><div class="gather-summary">${['ore','herb','energy'].map(k=>{const b=gatherBoost(s,k,PETS);return `<span>${{ore:'Đào khoáng',herb:'Hái thuốc',energy:'Hấp thu'}[k]} <b>+${b.toFixed(1)}% · ${gatherSeconds(b).toFixed(2)}s</b></span>`;}).join('')}</div><label>Hành vi đội hình <select id="deckStance">${Object.entries({aggressive:'Chủ động',defend:'Bảo vệ',passive:'Đi theo — tắt kỹ năng chiến đấu'}).map(([k,n])=>`<option value="${k}" ${s.companions.stance===k?'selected':''}>${n}</option>`).join('')}</select></label><div class="companion-layout"><section class="avatar-stage"><h3>${p.name} · ${GRADES[p.grade].color}</h3><canvas id="avatarCanvas" aria-label="Pet 3D"></canvas><div class="avatar-controls"><button id="avatarLeft">↶</button><span>Kéo để xoay</span><button id="avatarRight">↷</button></div></section><section><h3>${p.name}</h3><span class="grade-tag rarity-${p.grade}">${GRADES[p.grade].name}</span><p>${statsText}</p><p>${speed}</p><p>${PET_EFFECTS[p.shape]||'Hỗ trợ theo loài.'} Nhịp 3 giây.</p>${it?`<p>${it.id} · Nuôi dưỡng ${it.rank}/5 · Bảo vật ${it.treasure}/3 · ${it.protected?'Được bảo vệ':'Chưa bảo vệ'}</p><div class="toolbar"><button id="deployPet" ${!s.petDeck.includes(it.id)&&(s.petDeck.length>=slots||deployedPets(s).some(x=>x.species===key))?'disabled':''}>${s.petDeck.includes(it.id)?'Tháo khỏi đội':'Đeo vào ô trống'}</button><button id="protectPet">${it.protected?'Bỏ bảo vệ':'Bảo vệ khỏi ghép'}</button></div><p>Nuôi dưỡng: ${120*(it.rank+1)} đồng + ${3*(it.rank+1)} linh phách ${GRADES[p.grade].color}.</p><button id="raiseRoster" ${it.rank>=5||s.gold<120*(it.rank+1)||amount(s,'essence',p.grade)<3*(it.rank+1)?'disabled':''}>Nuôi dưỡng</button><p>Bảo vật: ${120*(it.treasure+1)} đồng + ${3*(it.treasure+1)} ngọc tinh + ${2*(it.treasure+1)} linh phách cùng màu.</p><button id="raiseTreasure" ${it.treasure>=3||s.gold<120*(it.treasure+1)||!canMaterials(s,{gem:3*(it.treasure+1),essence:2*(it.treasure+1)},p.grade)?'disabled':''}>Nâng bảo vật</button>`:'<p>Đây là mẫu trong danh mục; triệu hồi để nhận cá thể vào túi.</p>'}<h4>Triệu hồi thêm ${p.name}</h4><p>${100*(p.grade+1)} đồng + ${10*(p.grade+1)} linh phách ${GRADES[p.grade].color} (có ${amount(s,'essence',p.grade)}).</p><button id="summonRoster" ${s.petRoster.length>=500||!regionUnlocked(s,p.unlock)||s.gold<100*(p.grade+1)||amount(s,'essence',p.grade)<10*(p.grade+1)?'disabled':''}>Triệu hồi cá thể mới</button></section></div><h3>Túi pet thật · ${s.petRoster.length}/500</h3><label>Lọc màu <select id="petGrade"><option value="all">Tất cả</option>${GRADES.map((g,i)=>`<option value="${i}" ${String(filter)===String(i)?'selected':''}>${g.color}</option>`).join('')}</select></label><p>Chọn cá thể để xem/đeo; đánh dấu đúng bốn cá thể cùng màu để ghép. Không dùng pet đang đeo hoặc được bảo vệ.</p><div class="pet-owned">${roster.map(x=>{const d=PETS[x.species],locked=x.protected||s.petDeck.includes(x.id)||d.grade===4;return `<article class="rarity-${d.grade}"><button data-pet-id="${x.id}" class="${selected===x.id?'active':''}">${petPortrait(x.species)}<b>${d.name}</b><small>${x.id} · Bậc ${x.rank} · Bảo vật ${x.treasure}</small><small>${s.petDeck.includes(x.id)?'Đang đeo':x.protected?'Bảo vệ':'Trong túi'}</small></button><label><input type="checkbox" data-pet-fuse="${x.id}" ${locked?'disabled':''} ${fuse.includes(x.id)?'checked':''}> Chọn ghép</label></article>`;}).join('')||'<p>Chưa có pet thuộc màu này.</p>'}</div><div class="forge-confirm-box"><h3>Ghép 4 → 1 · đã chọn ${fuse.length}/4</h3><p>20% nhận pet màu kế; 80% nhận pet cùng màu. Tiêu hao cả 4 cá thể. Kết quả ngẫu nhiên trong màu, bậc 1, bảo vật 0. Không có cơ chế bảo hiểm.</p><p>${fuse.join(' + ')||'Chọn trực tiếp pet trong túi.'}</p><button id="fuseRoster" ${!game.canFusePets(fuse)?'disabled':''}>Xem trước ghép pet</button><button id="clearFuse">Bỏ chọn</button></div><details><summary>Danh mục 20 loài · mỗi màu 4 loài</summary><div class="companion-roster">${Object.entries(PETS).map(([k,d])=>`<button data-species="${k}" class="rarity-${d.grade}">${petPortrait(k)}<b>${d.name}</b><small>${GRADES[d.grade].color}</small></button>`).join('')}</div></details>`,'pets',{...s,previewCreature:p.shape,previewGrade:p.grade});
 $$('[data-nav]').forEach(b=>b.onclick=()=>showPanel(b.dataset.nav));$$('[data-deck]').forEach(b=>b.onclick=()=>{selected=b.dataset.deck;refresh();});$$('[data-pet-id]').forEach(b=>b.onclick=()=>{selected=b.dataset.petId;refresh();$('#modal').scrollTop=0;});$$('[data-species]').forEach(b=>b.onclick=()=>{catalog=b.dataset.species;selected=null;refresh();$('#modal').scrollTop=0;});
 $('#petGrade').onchange=e=>{filter=e.target.value;refresh();};$('#deckStance').onchange=e=>{game.setPetStance(e.target.value);refresh();};$('#summonRoster').onclick=()=>{const a=game.summonPet(key);if(a)selected=a.id;refresh();};$('#deployPet')?.addEventListener('click',()=>{if(s.petDeck.includes(it.id))game.removePet(it.id);else game.deployPet(it.id);refresh();});$('#protectPet')?.addEventListener('click',()=>{game.protectPet(it.id);fuse=fuse.filter(id=>id!==it.id);refresh();});$('#raiseRoster')?.addEventListener('click',()=>{game.raisePet(it.id);refresh();});$('#raiseTreasure')?.addEventListener('click',()=>{game.raisePet(it.id,true);refresh();});
 $$('[data-pet-fuse]').forEach(b=>b.onchange=()=>{if(b.checked){if(fuse.length<4)fuse.push(b.dataset.petFuse);}else fuse=fuse.filter(id=>id!==b.dataset.petFuse);refresh();});$('#clearFuse').onclick=()=>{fuse=[];refresh();};$('#fuseRoster').onclick=()=>{const ids=[...fuse];openModal(`<h2>Xác nhận ghép 4 pet</h2><p>Tiêu hao ${ids.join(', ')}. 20% tăng một màu, 80% giữ màu; chỉ nhận 1 cá thể bậc 1, bảo vật 0. Pet nguyên liệu và nâng cấp của chúng sẽ mất.</p><button id="confirmPetFusion">Ghép 4 pet đã chọn</button><button id="cancelPetFusion">Hủy</button>`,'pet-confirm');$('#confirmPetFusion').onclick=()=>{const out=game.fusePets(ids);if(out)selected=out.item.id;fuse=[];refresh();};$('#cancelPetFusion').onclick=()=>showPanel('pets');};return true;
}
